const bigPeriods=[['1mo','月K'],['1w','周K'],['1d','日K']];
const smallPeriods=[['30m','30分钟'],['60m','1小时'],['120m','2小时']];
const labels=Object.fromEntries([...bigPeriods,...smallPeriods]);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>typeof v==='number'&&Number.isFinite(v)?v.toLocaleString('zh-CN',{maximumFractionDigits:4}):'待数据';
const date=v=>{if(!v)return'未取得';const t=new Date(v);return Number.isFinite(+t)?t.toLocaleString('zh-CN',{hour12:false}):String(v)};
const tone=d=>d==='long'||d==='up'?'bull':d==='short'||d==='down'?'bear':'neutral';
const direction=d=>({long:'做多',short:'做空',up:'做多',down:'做空',both:'多空双向'}[d]||'待方向');
const taskState=s=>({active:'已启用',paused:'已暂停',archived:'已归档',draft:'待启用'}[s]||'待核验');
const observationState=s=>({'waiting-data':'待数据',baseline:'建立基线','waiting-direction':'等大周期同向','waiting-turn':'等MA10拐头','waiting-cross':'等价格穿越',triggered:'本轮已提醒',paused:'已暂停'}[s]||'待核验');
const deliveryState=s=>({pending:'待发送',sending:'发送中',accepted:'通道已接受',sent:'已发送',delivered:'已送达',failed:'发送失败',unknown:'结果待确认',skipped:'未发送'}[s]||'待核验');
const array=v=>Array.isArray(v)?v:[];
const finite=v=>typeof v==='number'&&Number.isFinite(v);

export function renderTrendUniverse(rows,{hour=false,search='',sector='all'}={}){
 const periods=[['1mo','月K'],['1w','周K'],['1d','日K'],['120m','2小时'],...(hour?[['60m','1小时']]:[]),['30m','30分钟']];
 const visible=array(rows).filter(r=>(sector==='all'||r.sector===sector)&&(!search||[r.code,r.name,r.symbol,r.sector].some(v=>String(v||'').toLowerCase().includes(search.toLowerCase()))));
 const cell=s=>{const valid=s?.status==='ok'||s?.status==='closed',value=valid?s.direction:null,kind=value===1?'bull':value===-1?'bear':'neutral',text=value===1?'↑ 向上':value===-1?'↓ 向下':valid&&value===0?'— 走平':s?.status==='stale'?'陈旧':'不足';return `<td><span class="tm-slope tm-${kind}" title="${esc(`MA10 ${num(s?.ma)}；前值 ${num(s?.previousMa)}；${date(s?.stamp)}；${s?.reason||''}`)}">${text}</span></td>`};
 return `<div class="tm-universe-count">${visible.length} / ${array(rows).length} 个品种 <span>只看MA10斜率 · 盘中未收线</span></div><div class="tm-universe-scroll"><table class="tm-universe-table"><thead><tr><th>品种</th>${periods.map(([,label])=>`<th>${label}<small>MA10</small></th>`).join('')}<th>警报</th></tr></thead><tbody>${visible.length?visible.map(r=>`<tr data-tm-row="${esc(r.code)}"><td><div class="tm-row-identity"><b>${esc(r.code)}</b><strong>${esc(r.name)}</strong><span class="tm-sector-tag">${esc(r.sector||'其他')}</span></div><small class="tm-row-meta" title="${esc(r.source||'来源待核验')}">${esc(r.symbol||'合约待核验')} · ${esc((r.quoteAt?date(r.quoteAt):'行情待更新')+(r.sessionActive===false?' · 休市':''))}</small></td>${periods.map(([p])=>cell(r.signals?.[p])).join('')}<td class="tm-alert-cell">${array(r.alerts).map(e=>{const recent=!e.readAt&&Number.isFinite(Date.parse(e.triggeredAt))&&Date.now()-Date.parse(e.triggeredAt)>=0&&Date.now()-Date.parse(e.triggeredAt)<=300000,period=e.period||e.evidence?.period||e.evidence?.smallPeriod,side=e.direction==='long'||e.direction==='up'?'多头':e.direction==='short'||e.direction==='down'?'空头':'方向待核验';return `<button type="button" data-tm-read="${esc(e.id)}" class="tm-alert tm-${tone(e.direction)} ${e.readAt?'tm-alert-read':recent?'tm-alert-unread':'tm-alert-history'}" title="${esc(`${date(e.triggeredAt)}；${e.condition||e.label||''}；${e.readAt?'已读，历史保留':'点击标记已读并停止闪烁'}`)}">${esc(labels[period]||period||'周期待核验')}${side}警报${e.readAt?'<small>已读</small>':recent?'':'<small>历史提醒</small>'}</button>`}).join('')||'<span class="tm-no-alert">—</span>'}</td></tr>`).join(''):`<tr><td colspan="${periods.length+2}"><div class="tm-empty">当前筛选没有品种；行情不足时会明确标注，不推算方向。</div></td></tr>`}</tbody></table></div>`;
}

export function defaultTrendDraft(){return {title:'周日同向 · 30分钟拐点',bigPeriods:['1w','1d'],smallPeriods:['30m'],direction:'both',scope:'all',codes:[],channels:['desktop','weixin'],status:'active'}};
export function validateTrendDraft(draft){
 if(!array(draft.bigPeriods).length)throw Error('至少勾选一个大周期');
 if(draft.bigPeriods.some(p=>!bigPeriods.some(([id])=>id===p)))throw Error('大周期只支持月K、周K、日K');
 if(!array(draft.smallPeriods).length)throw Error('至少勾选一个触发周期');
 if(draft.smallPeriods.some(p=>!smallPeriods.some(([id])=>id===p)))throw Error('触发周期只支持30分钟、1小时、2小时');
 if(!array(draft.channels).length)throw Error('至少选择一种提醒方式');
 if(draft.scope==='codes'&&!array(draft.codes).length)throw Error('请至少选择一个品种');
 if(!String(draft.title||'').trim())throw Error('请填写任务名称');
 return {...draft,title:String(draft.title).trim(),bigPeriods:[...new Set(draft.bigPeriods)],smallPeriods:[...new Set(draft.smallPeriods)],channels:[...new Set(draft.channels)],codes:[...new Set(draft.codes)]};
}
export function renderTrendTasks(tasks){
 const visible=array(tasks).filter(t=>t.status!=='archived');
 return visible.length?visible.map(t=>`<article class="tm-task ${tone(t.direction)}" data-trend-task="${esc(t.id)}"><div class="tm-task-head"><h3>${esc(t.title||t.name||'监控任务')}</h3><span class="tm-pill ${t.status==='active'?'on':''}">${taskState(t.status)}</span></div><p><b>${array(t.bigPeriods).map(p=>labels[p]||p).map(esc).join('＋')}</b> 同向 <span aria-hidden="true">→</span> <b>${array(t.smallPeriods).map(p=>labels[p]||p).map(esc).join(' / ')}</b> 拐头＋穿越</p><div class="tm-caption">${direction(t.direction)} · ${t.scope==='codes'?array(t.codes).length+'个品种':'全部品种当前主力'} · ${array(t.channels).map(c=>c==='weixin'?'微信':'桌面').join('＋')} · 第${num(t.version||1)}版</div><div class="tm-task-actions"><button type="button" data-tm-edit="${esc(t.id)}">修改条件</button><button type="button" data-tm-action="${t.status==='active'?'pause':'activate'}" data-tm-id="${esc(t.id)}">${t.status==='active'?'暂停':'启用'}</button><button type="button" data-tm-action="archive" data-tm-id="${esc(t.id)}">归档</button></div></article>`).join(''):'<div class="tm-empty">尚无监控任务。勾选周期后点“保存并启用”，小木会持续跟踪。</div>';
}
export function renderTrendEvents(events){
 const rows=array(events).filter(e=>e.kind==='ma-turn'||e.kind==='trend'||e.kind==='trend-turn'||e.ruleId?.startsWith('trend:'));
 return rows.length?`<div class="tm-table-wrap"><table><thead><tr><th>触发时间</th><th>品种 / 合约</th><th>方向与周期</th><th>价格 / MA10</th><th>触发依据</th><th>推送状态</th></tr></thead><tbody>${rows.map(e=>{const ev=e.evidence||{},period=e.period||ev.period||ev.smallPeriod,ma=e.ma??ev.ma??ev.ma10??ev.smallSignal?.ma;return `<tr><td>${esc(date(e.triggeredAt))}<small>行情 ${esc(date(e.quoteAt||ev.providerTime))}</small></td><td><b>${esc(e.code||'')} ${esc(e.name||'')}</b><small>${esc(e.symbol||ev.symbol||'具体合约待核验')}</small></td><td><b class="tm-${tone(e.direction)}">${direction(e.direction)} · ${esc(labels[period]||period||'周期待核验')}</b><small class="tm-live-tag">盘中未收线</small></td><td><b>${num(e.price)}</b><small>MA10 ${num(ma)}</small></td><td>${esc(e.condition||e.label||'MA10拐头且价格穿越')}<small>${esc(e.source||ev.source||'来源待核验')}</small><details><summary>查看证据</summary><pre>${esc(JSON.stringify(ev,null,2))}</pre></details></td><td>${array(e.deliveries).map(d=>`<span class="tm-receipt ${d.status==='failed'?'failed':''}">${d.channel==='weixin'?'微信':'桌面'}：${deliveryState(d.status)}${d.note?`<small>${esc(d.note)}</small>`:''}</span>`).join('')||'未取得发送回执'}</td></tr>`}).join('')}</tbody></table></div>`:'<div class="tm-empty">尚无新信号。启动时已在均线同一侧的历史状态不会补报为新穿越。</div>';
}
export function renderTrendObservations(observations){
 const rows=array(observations);
 return rows.length?`<div class="tm-table-wrap"><table><thead><tr><th>品种 / 具体合约</th><th>任务与小周期</th><th>当前进度</th><th>最新价格</th><th>数据时间</th></tr></thead><tbody>${rows.map(o=>`<tr><td><b>${esc(o.code||'')} ${esc(o.name||'')}</b><small>${esc(o.symbol||'合约待核验')}</small></td><td>${esc(o.taskTitle||'监控任务')}<small>${esc(labels[o.period]||o.period||'')}</small></td><td><b class="tm-${tone(o.direction)}">${observationState(o.status)}</b><small>${esc(o.reason||'')}</small></td><td>${num(o.price)}<small>${finite(o.smallSignal?.ma)?'MA10 '+num(o.smallSignal.ma):''}</small></td><td>${esc(date(o.lastObserved||o.quoteAt))}</td></tr>`).join('')}</tbody></table></div>`:'<div class="tm-empty">等待当前主力合约及实时K线。行情缺失时不会推算信号。</div>';
}

export function createTrendMonitorPage({host,notify=()=>{},fetchImpl=(...args)=>fetch(...args)}){
 let running=false,timer=null,pollTimer=null,busy=false,mounted=false,editId=null,payload={},catalog=[],login=null,actionBusy=false,requestVersion=0,draftMemory=defaultTrendDraft(),rowSearch='',rowSector='all';
 const q=s=>host.querySelector(s);
 const api=async(path,body)=>{const r=await fetchImpl('/api/trend-monitor/'+path,{cache:'no-store',...(body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),signal:AbortSignal.timeout(15000)});const data=await r.json();if(!r.ok)throw Error(data.error||'监控接口读取失败');return data};
 function mount(){
  if(host.querySelector('.trend-monitor-page'))return;
  const style=document.getElementById('trendMonitorStyle');if(!style){const link=document.createElement('link');link.id='trendMonitorStyle';link.rel='stylesheet';link.href='/trend-monitor-ui.css';document.head.append(link)}
  host.innerHTML=`<section class="trend-monitor-page"><header class="tm-intro"><div><h2>大周期定方向，小周期等拐点</h2><p>MA10拐头与价格穿越同时核对 · 多空镜像 · <span class="tm-live-tag">盘中即时，当前K线未收线</span></p></div><button type="button" data-tm-refresh>刷新状态</button></header><div class="tm-service-status" role="status" data-tm-runtime>正在读取监控状态…</div><div class="tm-layout"><section class="tm-panel tm-editor"><header><h2 data-tm-editor-title>设置监控任务</h2><span>勾选的大周期须全部同向</span></header><form id="trendTaskForm"><label class="tm-title-field">任务名称<input name="title" maxlength="100" required></label><fieldset><legend>方向周期 · MA10</legend><div class="tm-options">${bigPeriods.map(([id,label])=>`<label><input type="checkbox" name="bigPeriods" value="${id}"><span>${label}</span></label>`).join('')}</div><div class="tm-presets"><span>快捷选择</span>${[['1d','日'],['1w,1d','周日'],['1mo,1w','月周'],['1mo,1w,1d','月周日']].map(([v,l])=>`<button type="button" data-tm-preset="${v}">${l}</button>`).join('')}</div></fieldset><fieldset><legend>触发周期 · 拐头＋穿越</legend><div class="tm-options">${smallPeriods.map(([id,label])=>`<label><input type="checkbox" name="smallPeriods" value="${id}"><span>${label}</span></label>`).join('')}</div></fieldset><div class="tm-form-row"><label>观察方向<select name="direction"><option value="both">多空双向</option><option value="long">只看多头</option><option value="short">只看空头</option></select></label><label>品种范围<select name="scope"><option value="all">全部品种当前主力</option><option value="codes">指定品种</option></select></label></div><div data-tm-products hidden><label>选择品种</label><div class="tm-product-options" data-tm-catalog>正在读取品种…</div></div><fieldset><legend>提醒方式</legend><div class="tm-options"><label><input type="checkbox" name="channels" value="desktop"><span>桌面事件提醒</span></label><label><input type="checkbox" name="channels" value="weixin"><span>微信推送</span></label></div></fieldset><div class="tm-form-actions"><button class="primary" type="submit" data-tm-save>保存并启用</button><button type="button" data-tm-new>新建任务</button></div><p class="tm-caption" data-tm-form-note>同一拐点只提醒一次。修改条件会生成新版本，并重新建立观测基线。</p></form><details class="tm-method"><summary>提醒如何判定？</summary><p>勾选的大周期MA10全部向上，才观察小周期向上拐头与价格上穿；全部向下时镜像观察做空。MA10走平、反向或数据不足时等待。</p><p>先用连续行情建立基线；小周期MA10从反向或走平拐向目标方向后，等待价格跨过MA10。首次启动、断线重连、换合约时均重新建立基线，不把原有状态当成新穿越。</p><p>本页采用盘中即时判断，K线未收完，方向随后可能变化。退出页面仍会监控；小木服务停止、电脑休眠或网络中断时无法继续观察。</p></details></section><div class="tm-right"><section class="tm-panel"><header><h2>已设置的任务</h2><span data-tm-task-count></span></header><div data-tm-tasks class="tm-task-list"></div></section><section class="tm-panel tm-weixin"><header><h2>微信事件推送</h2><span data-tm-weixin-label>待核验</span></header><p data-tm-weixin-state>正在读取连接状态…</p><div data-tm-qr hidden></div><form data-tm-verify hidden><label>手机显示的验证数字<input name="code" inputmode="numeric" autocomplete="one-time-code" maxlength="12"></label><button type="submit">确认数字</button></form><div class="tm-form-actions"><button type="button" data-tm-login>连接微信</button><button type="button" data-tm-weixin-test>发送测试提醒</button><button type="button" data-tm-weixin-disconnect>断开</button></div><p class="tm-caption">扫码绑定后，先向机器人发一条消息，建立本人推送会话。测试提醒单独标明，不计入真实信号。</p></section></div></div><section class="tm-panel"><header><h2>最新触发事件</h2><span>事件保留触发依据和推送回执</span></header><div data-tm-events></div></section><details class="tm-panel tm-observations"><summary>全品种跟踪进度 <span data-tm-coverage></span></summary><div data-tm-observations></div></details><details class="tm-panel tm-gaps"><summary>数据缺口与运行说明 <span data-tm-gap-count></span></summary><div data-tm-gaps></div></details></section>`;
  const page=q('.trend-monitor-page'),layout=q('.tm-layout'),editor=q('.tm-editor'),taskPanel=q('[data-tm-tasks]').closest('section'),wx=q('.tm-weixin');
  const settings=document.createElement('details');settings.className='tm-settings tm-panel';settings.innerHTML='<summary>监控设置与任务管理 <span data-tm-task-summary></span></summary><div class="tm-settings-grid"></div>';settings.querySelector('div').append(editor,taskPanel);
  const filters=document.createElement('div');filters.className='tm-universe-filters';filters.innerHTML='<label>板块<select data-tm-row-sector><option value="all">全部板块</option></select></label><label class="tm-row-search">搜索<input type="search" data-tm-row-search placeholder="品种、代码或合约"></label><span>点击闪烁警报标记已读</span>';
  const universe=document.createElement('section');universe.className='tm-universe';universe.setAttribute('aria-label','全品种MA10方向与警报');universe.dataset.tmUniverse='';
  layout.replaceWith(wx,settings,filters,universe);wx.classList.remove('tm-panel');
  const eventPanel=q('[data-tm-events]').closest('section'),eventHistory=document.createElement('details');eventHistory.className='tm-panel tm-event-history';eventHistory.innerHTML='<summary>触发事件与证据历史</summary>';eventHistory.append(q('[data-tm-events]'));eventPanel.replaceWith(eventHistory);
  q('.tm-intro h2').textContent='全品种周期方向与警报';q('.tm-intro p').innerHTML='方向只按MA10斜率 · <span class="tm-bull">↑ 向上</span> / <span class="tm-bear">↓ 向下</span> · 灰色为走平或数据不足';
  host.addEventListener('click',click);host.addEventListener('change',change);host.addEventListener('input',input);host.addEventListener('submit',submit);mounted=true;fill(draftMemory);
 }
 function formDraft(){const form=q('#trendTaskForm'),checked=name=>[...form.querySelectorAll(`input[name="${name}"]:checked`)].map(e=>e.value);return {title:form.elements.title.value,bigPeriods:checked('bigPeriods'),smallPeriods:checked('smallPeriods'),direction:form.elements.direction.value,scope:form.elements.scope.value,codes:checked('codes'),channels:checked('channels'),status:'active'}}
 function fill(draft){const form=q('#trendTaskForm');if(!form)return;form.elements.title.value=draft.title||draft.name||'';form.elements.direction.value=draft.direction||'both';form.elements.scope.value=draft.scope==='codes'?'codes':'all';for(const field of form.querySelectorAll('input[type="checkbox"]'))field.checked=array(draft[field.name]).includes(field.value);q('[data-tm-products]').hidden=form.elements.scope.value!=='codes';q('[data-tm-editor-title]').textContent=editId?'修改任务条件':'设置监控任务';q('[data-tm-save]').textContent=editId?'保存新版并启用':'保存并启用'}
 function renderCatalog(){const selected=new Set(formDraft().codes);q('[data-tm-catalog]').innerHTML=catalog.length?catalog.map(p=>`<label><input type="checkbox" name="codes" value="${esc(p.code)}" ${selected.has(p.code)?'checked':''}><span><b>${esc(p.code)}</b> ${esc(p.name)}</span></label>`).join(''):'暂未取得具体主力合约列表'}
 function refreshParts(){
  const market=payload.market||{},coverage=payload.coverage||{},tasks=array(payload.tasks),observations=array(payload.observations),events=array(payload.events),latest=market.lastQuoteAt||market.quoteAt||market.heartbeatAt;
  const connected=market.status==='connected'&&market.heartbeatFresh!==false;
  q('[data-tm-runtime]').classList.toggle('tm-connected',connected);q('[data-tm-runtime]').innerHTML=`<b>${esc(market.message||({connected:'行情连接已建立',unconfigured:'行情待配置',disconnected:'行情已断开',stopped:'监控已停止',failed:'行情连接失败'}[market.status]||'监控行情待核验'))}</b><span>来源：${esc(market.source||market.provider||'待核验')} · 行情时间：${esc(date(latest))} · 监听 ${num(coverage.observed??market.subscribed??0)} / ${num(coverage.catalog??catalog.length)} 个品种</span>`;
  q('[data-tm-tasks]').innerHTML=renderTrendTasks(tasks);q('[data-tm-task-count]').textContent=`${tasks.filter(t=>t.status==='active').length} 个启用`;q('[data-tm-task-summary]').textContent=`${tasks.filter(t=>t.status==='active').length} 个启用 · 点开修改周期、方向与提醒方式`;
  renderUniverse();
  q('[data-tm-events]').innerHTML=renderTrendEvents(events);q('[data-tm-observations]').innerHTML=renderTrendObservations(observations);q('[data-tm-coverage]').textContent=`${observations.length} 条周期状态`;
  const gaps=observations.filter(o=>o.status==='waiting-data');q('[data-tm-gap-count]').textContent=gaps.length?`${gaps.length} 条待数据`:'';
  q('[data-tm-gaps]').innerHTML=`<p>${esc(payload.notice||'电脑保持运行、行情持续连接时，任务在后台跟踪。')}</p>`+(gaps.length?`<ul>${gaps.map(g=>`<li>${esc(g.code||g.symbol)} ${esc(labels[g.period]||g.period||'')}：${esc(g.reason||'行情不足，暂停判断')}</li>`).join('')}</ul>`:'<p>当前未报告额外缺口；以逐品种跟踪状态为准。</p>');renderWeixin(payload.weixin||login||{});
 }
 function renderUniverse(){
  const rows=Array.isArray(payload.rows)?payload.rows:catalog.map(c=>({...c,signals:{},alerts:[]})),sectors=[...new Set(rows.map(r=>r.sector||'其他'))],select=q('[data-tm-row-sector]');
  if(!sectors.includes(rowSector))rowSector='all';
  const signature=sectors.join('|');if(select.dataset.sectors!==signature){select.innerHTML='<option value="all">全部板块</option>'+sectors.map(s=>`<option value="${esc(s)}">${esc(s)}</option>`).join('');select.dataset.sectors=signature;}select.value=rowSector;
  const hour=array(payload.tasks).some(t=>t.status==='active'&&array(t.smallPeriods).includes('60m'));
  const scroll=q('.tm-universe-scroll'),top=scroll?.scrollTop||0;
  q('[data-tm-universe]').innerHTML=renderTrendUniverse(rows,{hour,search:rowSearch,sector:rowSector});q('.tm-universe-scroll').scrollTop=top;
 }
 function renderWeixin(wx){
  if(!q('[data-tm-weixin-state]'))return;const status=wx.state||wx.status||wx.login?.state||'unconfigured',ready=wx.pushReady===true||wx.ready===true,bound=wx.connected===true||wx.bound===true||ready||['connected','ready','waiting-context','bound'].includes(status);
  q('[data-tm-weixin-label]').textContent=ready?'可推送':bound?'已绑定，待会话':status==='waiting'||status==='pending'?'等待扫码':'待连接';
  q('[data-tm-weixin-state]').textContent=wx.note||wx.message||wx.error||wx.login?.error||({unconfigured:'微信尚未绑定',waiting:'请用本人微信扫码',pending:'请用本人微信扫码',expired:'二维码已过期，请重新连接',failed:'连接失败，请重试',ready:'已建立推送会话'}[status]||'微信连接状态待核验');
  const image=wx.login?.qr||wx.qrCodeImageUrl||wx.qrImage||wx.qrcodeImage||((/^data:image\/(?:png|svg\+xml);base64,/.test(wx.qrCodeUrl||''))?wx.qrCodeUrl:null),qr=q('[data-tm-qr]');
  const safeImage=typeof image==='string'&&(/^data:image\/png;base64,[A-Za-z0-9+/=]+$/.test(image)||/^https:\/\/[^\s"<>]+$/.test(image));
  qr.hidden=!safeImage||bound;if(safeImage&&qr.dataset.image!==image){qr.innerHTML=`<img alt="使用本人微信扫描连接二维码" src="${esc(image)}"><p>使用本人微信扫码确认</p>`;qr.dataset.image=image}
  q('[data-tm-verify]').hidden=wx.login?.needsCode!==true&&!['need_verifycode','need-verifycode','verify-required'].includes(status);q('[data-tm-weixin-test]').disabled=!ready||actionBusy;q('[data-tm-weixin-disconnect]').disabled=!bound||actionBusy;
 }
 async function refresh(){if(!running||busy)return;busy=true;const version=++requestVersion;try{const data=await api('status');if(!running||version!==requestVersion)return;payload=data;refreshParts();}catch(error){if(running&&version===requestVersion){q('[data-tm-runtime]').textContent='监控状态读取失败：'+error.message;q('[data-tm-runtime]').classList.remove('tm-connected')}}finally{if(version===requestVersion)busy=false}}
 async function action(work,success){if(actionBusy)return;actionBusy=true;for(const button of host.querySelectorAll('button[data-tm-save],button[data-tm-login]'))button.disabled=true;try{await work();if(success)notify(success);await refresh()}catch(error){notify(error.message)}finally{actionBusy=false;for(const button of host.querySelectorAll('button[data-tm-save],button[data-tm-login]'))button.disabled=false;renderWeixin(payload.weixin||login||{})}}
 async function click(event){const b=event.target.closest('button');if(!b||!host.contains(b))return;
  if(b.hasAttribute('data-tm-refresh'))return void refresh();
  if(b.dataset.tmRead)return void action(async()=>{await api('events/'+encodeURIComponent(b.dataset.tmRead)+'/read',{});for(const row of array(payload.rows))for(const alert of array(row.alerts))if(alert.id===b.dataset.tmRead)alert.readAt=new Date().toISOString();renderUniverse()},'警报已读，记录保留');
  if(b.dataset.tmPreset!==undefined){const selected=b.dataset.tmPreset.split(',');for(const field of q('#trendTaskForm').querySelectorAll('input[name="bigPeriods"]'))field.checked=selected.includes(field.value);return}
  if(b.hasAttribute('data-tm-new')){editId=null;fill(defaultTrendDraft());return}
  if(b.dataset.tmEdit){const task=array(payload.tasks).find(t=>t.id===b.dataset.tmEdit);if(task){editId=task.id;fill(task);q('#trendTaskForm').scrollIntoView?.({block:'nearest',behavior:'smooth'})}return}
  if(b.dataset.tmAction)return void action(()=>api('tasks/'+encodeURIComponent(b.dataset.tmId)+'/'+b.dataset.tmAction,{}),'任务状态已更新');
  if(b.hasAttribute('data-tm-login'))return void action(async()=>{login=await api('weixin/login',{});payload.weixin=login;renderWeixin(login)},'请扫码连接微信');
  if(b.hasAttribute('data-tm-weixin-test'))return void action(async()=>{const result=await api('weixin/test',{});notify(result.message||'测试请求已提交，请以发送回执和手机实际接收为准')});
  if(b.hasAttribute('data-tm-weixin-disconnect'))return void action(async()=>{await api('weixin/disconnect',{});login=null},'微信已断开');
 }
 function change(event){if(event.target.name==='scope')q('[data-tm-products]').hidden=event.target.value!=='codes';if(event.target.hasAttribute('data-tm-row-sector')){rowSector=event.target.value;renderUniverse()}}
 function input(event){if(event.target.hasAttribute('data-tm-row-search')){rowSearch=event.target.value;renderUniverse()}}
 function submit(event){
  if(event.target.id==='trendTaskForm'){event.preventDefault();let draft;try{draft=validateTrendDraft(formDraft())}catch(e){notify(e.message);return}void action(async()=>{const result=await api('tasks'+(editId?'/'+encodeURIComponent(editId):''),draft);editId=null;fill(defaultTrendDraft());notify((result.title||draft.title)+' 已保存并启用')});}
  else if(event.target.hasAttribute('data-tm-verify')){event.preventDefault();const code=event.target.elements.code.value.trim();if(!/^\d{1,12}$/.test(code))return notify('请输入手机显示的验证数字');void action(async()=>{login=await api('weixin/verify',{id:payload.weixin?.login?.id||login?.login?.id,code});payload.weixin=login;renderWeixin(login)})}
 }
 function start(){if(running&&host.querySelector('.trend-monitor-page'))return;if(!host.querySelector('.trend-monitor-page')){if(mounted){host.removeEventListener('click',click);host.removeEventListener('change',change);host.removeEventListener('input',input);host.removeEventListener('submit',submit)}mount()}running=true;void refresh();timer=setInterval(()=>{if(document.visibilityState!=='hidden')void refresh()},4000);void api('catalog').then(data=>{if(!running)return;catalog=array(data.items);renderCatalog();renderUniverse()}).catch(()=>{})}
 function stop(){if(q('#trendTaskForm'))draftMemory=formDraft();running=false;requestVersion++;clearInterval(timer);clearInterval(pollTimer);timer=null;busy=false;}
 return {start,stop,refresh};
}
